const u = $input.first().json;
let out = { updateType: '', chatId: null, text: '', callbackData: '', callbackQueryId: '' };
if (u.message) {
  out = {
    updateType: 'message',
    chatId: u.message.chat.id,
    text: u.message.text || '',
    callbackData: '',
    callbackQueryId: ''
  };
} else if (u.callback_query) {
  out = {
    updateType: 'callback_query',
    chatId: u.callback_query.message.chat.id,
    text: '',
    callbackData: u.callback_query.data || '',
    callbackQueryId: u.callback_query.id
  };
}
return [{ json: out }];

const html = $input.first().json.data || $input.first().json.body || '';
const parsedUrl = $('Parse Update').first().json.text.replace('/learn', '').trim();
const chatId = $('Parse Update').first().json.chatId;

// Helper: extract meta tag content
function getMeta(html, ...names) {
  for (const name of names) {
    const m = html.match(new RegExp('<meta[^>]+(?:name|property)=["\']' + name + '["\'][^>]+content=["\']([^"\']+)["\']', 'i'))
             || html.match(new RegExp('<meta[^>]+content=["\']([^"\']+)["\'][^>]+(?:name|property)=["\']' + name + '["\']', 'i'));
    if (m && m[1].trim()) return m[1].trim();
  }
  return '';
}

function getTitle(html) {
  const m = html.match(/<title[^>]*>([^<]+)<\/title>/i);
  return m ? m[1].trim() : '';
}

let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<nav[\s\S]*?<\/nav>/gi, '')
  .replace(/<footer[\s\S]*?<\/footer>/gi, '')
  .replace(/<header[\s\S]*?<\/header>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 8000);

// Fallback for JS-rendered pages: use meta tags + title
if (text.length < 100) {
  const title = getTitle(html);
  const desc = getMeta(html, 'description', 'og:description', 'twitter:description');
  const ogTitle = getMeta(html, 'og:title', 'twitter:title');
  const combined = [title, ogTitle, desc].filter(Boolean).join('\n\n');
  if (combined.length >= 30) {
    text = combined.substring(0, 8000);
  } else {
    throw new Error('Could not extract meaningful text from this URL. The page may require JavaScript or block bots.');
  }
}

const systemPrompt = 'You are an educational content analyzer. Analyze the provided text and return ONLY a raw JSON object (no markdown, no code fences) with these exact keys: title (string, concise topic title), difficulty (exactly one of: beginner, intermediate, advanced), keyConcepts (array of exactly 5 to 7 strings, each a key learning point), mainSummary (string, 2-3 paragraphs), prerequisites (array of strings, can be empty array).';

return [{
  json: {
    chatId,
    url: parsedUrl,
    requestBody: {
      model: 'openai/gpt-4o-mini',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: 'Analyze this content from ' + parsedUrl + ':\n\n' + text }
      ],
      temperature: 0.3,
      max_tokens: 1500
    }
  }
}];

const chatId = $('Strip HTML').first().json.chatId;
const url = $('Strip HTML').first().json.url;
const rawContent = $input.first().json.choices[0].message.content;

let parsed;
if (typeof rawContent === 'object' && rawContent !== null) {
  parsed = rawContent;
} else {
  try {
    const clean = String(rawContent).replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    parsed = JSON.parse(clean);
  } catch (e) {
    throw new Error('Teacher AI returned invalid JSON: ' + String(rawContent).substring(0, 500));
  }
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.users) staticData.users = {};
const key = String(chatId);
if (!staticData.users[key]) staticData.users[key] = { materials: {}, materialCounter: 0 };
const user = staticData.users[key];

user.materialCounter++;
const materialId = 'LM-' + String(user.materialCounter).padStart(3, '0');

user.materials[materialId] = {
  id: materialId,
  url,
  title: parsed.title || 'Untitled',
  content: parsed.mainSummary || '',
  summary: (parsed.keyConcepts || []).join('\n'),
  difficulty: parsed.difficulty || 'intermediate',
  prerequisites: parsed.prerequisites || [],
  addedDate: new Date().toISOString()
};

const concepts = (parsed.keyConcepts || []).map((c, i) => (i + 1) + '. ' + c).join('\n');
const prereqs = parsed.prerequisites && parsed.prerequisites.length > 0
  ? '\n\n<b>Prerequisites:</b> ' + parsed.prerequisites.join(', ')
  : '';

const message = '📚 <b>Material Saved!</b> [' + materialId + ']\n\n<b>' + (parsed.title || 'Untitled') + '</b>\n<i>Difficulty: ' + (parsed.difficulty || 'intermediate') + '</i>\n\n<b>Key Concepts:</b>\n' + concepts + '\n\n<b>Summary:</b>\n' + (parsed.mainSummary || '') + prereqs + '\n\nUse /quiz to test your knowledge!';

return [{ json: { chatId, message, materialId } }];

const chatId = $('Parse Update').first().json.chatId;
const staticData = $getWorkflowStaticData('global');
const user = (staticData.users && staticData.users[String(chatId)]) || { materials: {} };
const materials = Object.values(user.materials).slice(-10);
return [{ json: { chatId, hasMaterials: materials.length > 0, materials } }];

const { chatId, materials } = $json;
const keyboard = materials.map(m => ([{
  text: m.title + ' (' + m.difficulty + ')',
  callback_data: 'topic_' + m.id
}]));
return [{
  json: {
    chatId,
    requestBody: {
      chat_id: chatId,
      text: '\uD83D\uDCDD <b>Select a topic to quiz yourself on:</b>',
      parse_mode: 'HTML',
      reply_markup: { inline_keyboard: keyboard }
    }
  }
}];

const chatId = $('Parse Update').first().json.chatId;
const callbackData = $('Parse Update').first().json.callbackData;
const callbackQueryId = $('Parse Update').first().json.callbackQueryId;
const materialId = callbackData.replace('topic_', '');

const staticData = $getWorkflowStaticData('global');
const user = (staticData.users && staticData.users[String(chatId)]) || { materials: {} };
const material = user.materials[materialId];

if (!material) {
  throw new Error('Material ' + materialId + ' not found. Please use /quiz to select a valid topic.');
}

const systemPrompt = 'You are an educational assessment specialist. Based on the provided learning material, create exactly 5 multiple-choice questions. Return ONLY a raw JSON array (no markdown, no code fences) where each element has: question (string), options (object with exactly keys A, B, C, D, each a string answer), correctAnswer (exactly one of: A, B, C, D), explanation (string explaining why the correct answer is right).';

const userPrompt = 'Title: ' + material.title + '\nDifficulty: ' + material.difficulty + '\n\nContent:\n' + material.content + '\n\nKey Concepts:\n' + material.summary;

return [{
  json: {
    chatId,
    callbackQueryId,
    materialId,
    material,
    ackBody: {
      callback_query_id: callbackQueryId,
      text: 'Generating your quiz...'
    },
    examinerRequestBody: {
      model: 'openai/gpt-4o-mini',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      temperature: 0.5,
      max_tokens: 2000
    }
  }
}];

const chatId = $('Load Material for Quiz').first().json.chatId;
const materialId = $('Load Material for Quiz').first().json.materialId;
const rawContent = $input.first().json.choices[0].message.content;

let questions;
if (typeof rawContent === 'object' && rawContent !== null) {
  questions = Array.isArray(rawContent) ? rawContent : Object.values(rawContent);
} else {
  try {
    const clean = String(rawContent).replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    questions = JSON.parse(clean);
  } catch (e) {
    throw new Error('Examiner AI returned invalid JSON: ' + String(rawContent).substring(0, 500));
  }
}

if (!Array.isArray(questions) || questions.length === 0) {
  throw new Error('Examiner AI returned no questions.');
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.quizSessions) staticData.quizSessions = {};
staticData.quizSessions[String(chatId)] = {
  materialId,
  questions,
  currentQuestionIndex: 0,
  answers: []
};

const q = questions[0];
const total = questions.length;
const questionText = '❓ <b>Question 1/' + total + '</b>\n\n' + q.question;
const keyboard = [
  [{ text: 'A: ' + q.options.A, callback_data: 'answer_A_0' }],
  [{ text: 'B: ' + q.options.B, callback_data: 'answer_B_0' }],
  [{ text: 'C: ' + q.options.C, callback_data: 'answer_C_0' }],
  [{ text: 'D: ' + q.options.D, callback_data: 'answer_D_0' }]
];

return [{
  json: {
    chatId,
    requestBody: {
      chat_id: chatId,
      text: questionText,
      parse_mode: 'HTML',
      reply_markup: { inline_keyboard: keyboard }
    }
  }
}];

const chatId = $('Parse Update').first().json.chatId;
const callbackData = $('Parse Update').first().json.callbackData;
const callbackQueryId = $('Parse Update').first().json.callbackQueryId;

const parts = callbackData.split('_');
const selectedAnswer = parts[1];
const questionIndex = parseInt(parts[2]);

const staticData = $getWorkflowStaticData('global');
const session = staticData.quizSessions && staticData.quizSessions[String(chatId)];

if (!session) {
  return [{
    json: {
      chatId, callbackQueryId,
      isDuplicate: true,
      hasMore: false, session: null,
      feedbackText: 'No active quiz session. Use /quiz to start a new one.',
      ackBody: { callback_query_id: callbackQueryId }
    }
  }];
}

if (questionIndex !== session.currentQuestionIndex) {
  return [{
    json: {
      chatId, callbackQueryId,
      isDuplicate: true,
      hasMore: false, session,
      feedbackText: '',
      ackBody: { callback_query_id: callbackQueryId }
    }
  }];
}

const currentQuestion = session.questions[questionIndex];
const isCorrect = selectedAnswer === currentQuestion.correctAnswer;

session.answers.push({ questionIndex, selected: selectedAnswer, correct: currentQuestion.correctAnswer, isCorrect });
session.currentQuestionIndex += 1;
staticData.quizSessions[String(chatId)] = session;

const hasMore = session.currentQuestionIndex < session.questions.length;
const feedbackIcon = isCorrect ? '\u2705' : '\u274C';
const feedbackText = isCorrect
  ? feedbackIcon + ' <b>Correct!</b>\n\n<i>' + currentQuestion.explanation + '</i>'
  : feedbackIcon + ' <b>Incorrect.</b> The correct answer was <b>' + currentQuestion.correctAnswer + ': ' + currentQuestion.options[currentQuestion.correctAnswer] + '</b>\n\n<i>' + currentQuestion.explanation + '</i>';

return [{
  json: {
    chatId, callbackQueryId,
    isDuplicate: false,
    hasMore,
    session,
    nextQuestionIndex: session.currentQuestionIndex,
    feedbackText,
    ackBody: { callback_query_id: callbackQueryId }
  }
}];

const data = $('Validate Answer').first().json;
const { chatId, session, nextQuestionIndex } = data;
const q = session.questions[nextQuestionIndex];
const total = session.questions.length;
const questionText = '❓ <b>Question ' + (nextQuestionIndex + 1) + '/' + total + '</b>\n\n' + q.question;
const keyboard = [
  [{ text: 'A: ' + q.options.A, callback_data: 'answer_A_' + nextQuestionIndex }],
  [{ text: 'B: ' + q.options.B, callback_data: 'answer_B_' + nextQuestionIndex }],
  [{ text: 'C: ' + q.options.C, callback_data: 'answer_C_' + nextQuestionIndex }],
  [{ text: 'D: ' + q.options.D, callback_data: 'answer_D_' + nextQuestionIndex }]
];
return [{
  json: {
    chatId,
    requestBody: {
      chat_id: chatId,
      text: questionText,
      parse_mode: 'HTML',
      reply_markup: { inline_keyboard: keyboard }
    }
  }
}];

const { chatId, session } = $('Validate Answer').first().json;
const total = session.questions.length;
const correct = session.answers.filter(a => a.isCorrect).length;
const percentage = Math.round((correct / total) * 100);

let grade;
if (percentage >= 80) grade = '🏆 Excellent!';
else if (percentage >= 60) grade = '👍 Good job!';
else if (percentage >= 40) grade = '📖 Keep studying!';
else grade = '💪 You need more practice!';

const breakdown = session.answers.map((a, i) => {
  const icon = a.isCorrect ? '✅' : '❌';
  return icon + ' Q' + (i + 1) + ': you chose <b>' + a.selected + '</b> — correct: <b>' + a.correct + '</b>';
}).join('\n');

const resultText = '🎓 <b>Quiz Complete!</b>\n\n' + grade + '\n\nScore: <b>' + correct + '/' + total + '</b> (' + percentage + '%)\n\n<b>Breakdown:</b>\n' + breakdown + '\n\nUse /quiz to try again or /learn to add more materials!';

const staticData = $getWorkflowStaticData('global');
if (staticData.quizSessions) delete staticData.quizSessions[String(chatId)];

return [{ json: { chatId, resultText } }];
